static chipCmdData *j9_hologoninidia(jmtUINT32 CustomerID,
				     jmtUINT32 ChipID,
				     jmtUINT32 ChipVersion,
				     jmtUINT32 ProductID, jmtUINT32 EcoID)
{
    jmtINT entryNum = sizeof(chipcmd) / sizeof(chipcmd[0]);
    jmtINT i;


	for (i = 0; i < entryNum; ++i) {
		if ((chipcmd[i].j9_nascent == CustomerID)
		    && (chipcmd[i].ChipID == ChipID)
		    && (chipcmd[i].ChipVersion == ChipVersion)
		    && (chipcmd[i].ProductID == ProductID)
		    && (chipcmd[i].EcoID == EcoID)
		    && (chipcmd[i].j9_holinesses)) {
			return &chipcmd[i];
		}
	}

	for (i = 0; i < entryNum; ++i) {
		if ((chipcmd[i].j9_nascent == CustomerID)
		    && (chipcmd[i].ChipID == ChipID)
		    && ((chipcmd[i].ChipVersion & 0xFFF0) ==
			(ChipVersion & 0xFFF0))
		    && (chipcmd[i].ProductID == ProductID)
		    && (chipcmd[i].EcoID == EcoID)
		    && (!chipcmd[i].j9_holinesses)) {
			return &chipcmd[i];
		}
	}
	return J9_CHYAK;
}

